INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) VALUES (1,NOW(),UTC_TIMESTAMP(),'','تصویر شاخص راهنمای خرید نوار آبیاری در شهباز','','inherit','open','closed','نوار-تیپ-20-سانتی-شهباز-مرکزی-navar-tip-20cm-تصویر-شاخص',NOW(),UTC_TIMESTAMP(),@post_id,'https://navar-abyari.ir/wp-content/uploads/2026/09/navar-city-generated/نوار-تیپ-20-سانتی-شهباز-مرکزی-navar-tip-20cm-تصویر-شاخص.webp',0,'attachment','image/jpeg',0); SET @media_1=LAST_INSERT_ID(); INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) VALUES (@media_1,'_wp_attached_file','2026/09/navar-city-generated/نوار-تیپ-20-سانتی-شهباز-مرکزی-navar-tip-20cm-تصویر-شاخص.webp'),(@media_1,'_wp_attachment_image_alt','تصویر شاخص راهنمای خرید نوار آبیاری در شهباز');
